const { deepCloneObject } = require('../../../src/options/clone')
const { deepClone } = require('../../../src/options/clone')

jest.mock('../../../src/options/clone', () => {
  const originalModule = jest.requireActual('../../../src/options/clone')
  return {
    ...originalModule,
    deepClone: jest.fn()
  }
})

describe('deepCloneObject', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  it.skip('should return an empty object if input is an empty object', () => {
    const input = {}
    const result = deepCloneObject(input)
    expect(result).toEqual({})
    expect(deepClone).not.toHaveBeenCalled()
  })

  it.skip('should shallow copy properties and descriptors', () => {
    const input = {
      a: 1,
      b: 'test',
    }
    deepClone.mockImplementation((val) => val)

    const result = deepCloneObject(input)

    expect(result).not.toBe(input)
    expect(result).toEqual(input)
    expect(deepClone).toHaveBeenCalledTimes(2)
    expect(deepClone).toHaveBeenCalledWith(1)
    expect(deepClone).toHaveBeenCalledWith('test')
  })

  it.skip('should clone values using deepClone', () => {
    const mockValue = {}
    const mockClonedValue = {}
    const input = {
      key: mockValue,
    }
    deepClone.mockReturnValue(mockClonedValue)

    const result = deepCloneObject(input)

    expect(result.key).toBe(mockClonedValue)
    expect(deepClone).toHaveBeenCalledWith(mockValue)
  })

  it.skip('should copy enumerable property descriptors', () => {
    const input = { a: 1 }
    const descriptor = Object.getOwnPropertyDescriptor(input, 'a')
    deepClone.mockImplementation((val) => val)

    const result = deepCloneObject(input)
    const resultDescriptor = Object.getOwnPropertyDescriptor(result, 'a')

    expect(resultDescriptor.enumerable).toBe(descriptor.enumerable)
    expect(resultDescriptor.writable).toBe(descriptor.writable)
    expect(resultDescriptor.configurable).toBe(descriptor.configurable)
  })

  it.skip('should copy non-enumerable properties', () => {
    const input = {}
    Object.defineProperty(input, 'hidden', {
      value: 'secret',
      enumerable: false,
    })
    deepClone.mockImplementation((val) => val)

    const result = deepCloneObject(input)

    expect(Object.getOwnPropertyDescriptor(result, 'hidden').enumerable).toBe(false)
    expect(result.hidden).toBe('secret')
  })

  it.skip('should handle Symbol keys', () => {
    const symKey = Symbol('test')
    const input = {
      [symKey]: 'symbolValue',
    }
    deepClone.mockImplementation((val) => val)

    const result = deepCloneObject(input)

    expect(result[symKey]).toBe('symbolValue')
    expect(deepClone).toHaveBeenCalledWith('symbolValue')
  })

  it.skip('should maintain specific descriptor attributes (writable, configurable)', () => {
    const input = {}
    Object.defineProperty(input, 'fixed', {
      value: 'fixedValue',
      writable: false,
      configurable: false,
    })
    deepClone.mockImplementation((val) => val)

    const result = deepCloneObject(input)
    const descriptor = Object.getOwnPropertyDescriptor(result, 'fixed')

    expect(descriptor.writable).toBe(false)
    expect(descriptor.configurable).toBe(false)
  })

  it.skip('should handle getters and setters by copying their descriptors', () => {
    const input = {
      get getter() {
        return 'get'
      },
      set setter(val) {
        this._val = val
      },
    }

    const result = deepCloneObject(input)
    const getterDescriptor = Object.getOwnPropertyDescriptor(input, 'getter')
    const resultGetterDescriptor = Object.getOwnPropertyDescriptor(result, 'getter')

    expect(resultGetterDescriptor.get).toBe(getterDescriptor.get)
    expect(resultGetterDescriptor.set).toBe(getterDescriptor.set)
  })

  it.skip('should ensure the result is a new object and not a reference', () => {
    const input = {}
    const result = deepCloneObject(input)

    expect(result).not.toBe(input)
  })
})

