const { getErrorPluginInfo, isPlainObj, assignError } = mainModule

describe('applyPluginProperties', () => {
  let mockError
  let mockPlugin
  let mockPlugins

  beforeEach(() => {
    jest.clearAllMocks()

    mockError = new Error('Test error')
    mockPlugin = {
      fullName: 'test-plugin',
      properties: undefined,
    }
    mockPlugins = [mockPlugin]

    // Default behavior for mocks to pass through successful flow
    getErrorPluginInfo.mockReturnValue({ error: mockError, plugins: mockPlugins, plugin: mockPlugin })
    isPlainObj.mockReturnValue(true)
    assignError.mockImplementation(() => {})
  })

  test.skip('should return early if plugin properties are undefined', () => {
    mockPlugin.properties = undefined

    applyPluginProperties({ error: mockError, plugin: mockPlugin, plugins: mockPlugins })

    expect(getErrorPluginInfo).not.toHaveBeenCalled()
    expect(assignError).not.toHaveBeenCalled()
  })

  test.skip('should call assignError if properties function returns a plain object', () => {
    const newProps = { foo: 'bar' }
    mockPlugin.properties = jest.fn(() => newProps)

    applyPluginProperties({ error: mockError, plugin: mockPlugin, plugins: mockPlugins })

    expect(mockPlugin.properties).toHaveBeenCalled()
    expect(getErrorPluginInfo).toHaveBeenCalledWith({ error: mockError, plugins: mockPlugins, plugin: mockPlugin })
