        `Plugin "test-plugin"'s "properties()" must return a plain object: ${invalidProps}`,
      ),
    )
  })

  test.skip('should handle properties function returning null', () => {
    const nullProps = null
    mockPlugin.properties = jest.fn(() => nullProps)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      applyPluginProperties({ error: mockError, plugin: mockPlugin, plugins: mockPlugins })
    }).toThrow(
      new TypeError(
        `Plugin "test-plugin"'s "properties()" must return a plain object: ${nullProps}`,
      ),
    )
  })

  test.skip('should handle properties function returning an array', () => {
    const arrayProps = ['foo', 'bar']
    mockPlugin.properties = jest.fn(() => arrayProps)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      applyPluginProperties({ error: mockError, plugin: mockPlugin, plugins: mockPlugins })
    }).toThrow(
      new TypeError(
        `Plugin "test-plugin"'s "properties()" must return a plain object: ${arrayProps}`,
      ),
    )
  })

  test.skip('should pass correct info object from getErrorPluginInfo to properties function', () => {
