    mockPlugin.properties = jest.fn(() => ({ key: 'value' }))
    getErrorPluginInfo.mockReturnValue(info)

    applyPluginProperties({ error: mockError, plugin: mockPlugin, plugins: mockPlugins })

    expect(mockPlugin.properties).toHaveBeenCalledWith(info)
  })
})

