test/subclass/validate/validateSubclass..source:
const { validateSubclass } = require('../../../src/subclass/validate');

describe('validateSubclass', () => {
  let classesDataMock;

  beforeEach(() => {
    jest.resetModules();
    classesDataMock = new Set();

    jest.doMock('../../../src/subclass/validate', () => {
      // We cannot return the actual function because it closes over the original classesData.
      // We must redefine the function here to close over the mock.
      const validateSubclass = (ErrorClass) => {
        if (classesDataMock.has(ErrorClass)) {
          return;
        }
        const { name } = ErrorClass;
        const { name: parentName } = Object.getPrototypeOf(ErrorClass);
        const error = new Error(
          `"new ${name}()" must not be directly called.
This error class should be created like this instead:
  export const ${name} = ${parentName}.subclass('${name}')`
        );
        throw error;
      };

      return {
        validateSubclass,
        classesData: classesDataMock
      };
    });
  });

  it('should return without error if the ErrorClass is in classesData', () => {
    const { validateSubclass } = require('../../../src/subclass/validate');
    class MyError extends Error {}
    classesDataMock.add(MyError);

    expect(() => validateSubclass(MyError)).not.toThrow();
  });

  it('should throw an error if the ErrorClass is not in classesData', () => {
    const { validateSubclass } = require('../../../src/subclass/validate');
    class MyError extends Error {}

    expect(() => validateSubclass(MyError)).toThrow(
      `"new MyError()" must not be directly called.
This error class should be created like this instead:
  export const MyError = Error.subclass('MyError')`
    );
  });

  it('should include correct parent name in error message', () => {
    const { validateSubclass } = require('../../../src/subclass/validate');
    class ParentError extends Error {}
    class ChildError extends ParentError {}

    expect(() => validateSubclass(ChildError)).toThrow(
      `"new ChildError()" must not be directly called.
This error class should be created like this instead:
  export const ChildError = ParentError.subclass('ChildError')`
    );
  });

  it('should handle classes with Function.prototype as parent', () => {
    const { validateSubclass } = require('../../../src/subclass/validate');
    class StandaloneClass {}

    expect(() => validateSubclass(StandaloneClass)).toThrow(
      `"new StandaloneClass()" must not be directly called.
This error class should be created like this instead:
  export const StandaloneClass = .subclass('StandaloneClass')`
    );
  });
});

