    const mockPluginA = { id: 'A' };
    const mockPluginB = { id: 'B' };
    const mockPluginC = { id: 'C' };

    normalizeMethods
      .mockReturnValueOnce(mockPluginA)
      .mockReturnValueOnce(mockPluginB)
      .mockReturnValueOnce(mockPluginC);

    const result = normalizeAllMethods(mockPlugin);

    expect(normalizeMethods).toHaveBeenCalledTimes(3);

    expect(normalizeMethods).toHaveBeenNthCalledWith(1, {
      ...INSTANCE_METHODS,
      plugin: mockPlugin,
      propName: 'instanceMethods',
    });

    expect(normalizeMethods).toHaveBeenNthCalledWith(2, {
      ...STATIC_METHODS,
      plugin: mockPluginA,
      propName: 'instanceMethods',
    });

    expect(normalizeMethods).toHaveBeenNthCalledWith(3, {
      ...STATIC_METHODS,
      plugin: mockPluginB,
      propName: 'staticMethods',
    });

    expect(result).toEqual(mockPluginC);
  });

  it.skip('should pass through the results of normalizeMethods sequentially', () => {
