    const intermediateA = { name: 'A' };
    const intermediateB = { name: 'B' };
    const finalResult = { name: 'final' };

    normalizeMethods
      .mockReturnValueOnce(intermediateA)
      .mockReturnValueOnce(intermediateB)
      .mockReturnValueOnce(finalResult);

    const result = normalizeAllMethods(inputPlugin);

    expect(normalizeMethods).toHaveBeenCalledWith(expect.objectContaining({ plugin: inputPlugin }));
    expect(normalizeMethods).toHaveBeenCalledWith(expect.objectContaining({ plugin: intermediateA }));
    expect(normalizeMethods).toHaveBeenCalledWith(expect.objectContaining({ plugin: intermediateB }));
    expect(result).toBe(finalResult);
  });
});

