describe('prefixCause', () => {
  beforeEach(() => {
    setErrorMessage.mockClear();
  });

  it('should return empty string and set error message with name only when cause.message is not a string', () => {
    const cause = { name: 'Error' };
    const result = prefixCause(cause);

    expect(result).toBe('');
    // Since setErrorMessage is mocked, we just verify the function completes and returns correctly.
  });

  it('should return empty string and set error message with name only when cause.message is empty string', () => {
    const cause = { name: 'Error', message: '' };
    const result = prefixCause(cause);

    expect(result).toBe('');
  });

  it('should return old message and set error message with name and old message when cause.message is non-empty string', () => {
    const oldMessage = 'Something went wrong';
    const cause = { name: 'Error', message: oldMessage };
    const result = prefixCause(cause);

    expect(result).toBe(oldMessage);
  });

  it('should handle cause with non-string message type (e.g., null)', () => {
    const cause = { name: 'TypeError', message: null };
    const result = prefixCause(cause);

    expect(result).toBe('');
  });

  it('should handle cause with non-string message type (e.g., number)', () => {
    const cause = { name: 'RangeError', message: 42 };
    const result = prefixCause(cause);

    expect(result).toBe('');
  });

  it('should handle cause with non-string message type (e.g., object)', () => {
    const cause = { name: 'CustomError', message: { details: 'oops' } };
    const result = prefixCause(cause);

    expect(result).toBe('');
  });
});

