test/options/clone/deepClone.test.js.source:
const deepClone = require('../../../src/options/clone').deepClone;

describe('deepClone', () => {
  it('should return primitive values as is', () => {
    expect(deepClone(null)).toBeNull();
    expect(deepClone(undefined)).toBeUndefined();
    expect(deepClone(42)).toBe(42);
    expect(deepClone('hello')).toBe('hello');
    expect(deepClone(true)).toBe(true);
    expect(deepClone(false)).toBe(false);
  });

  it('should clone arrays recursively', () => {
    const input = [1, 2, 3];
    const output = deepClone(input);
    expect(output).toEqual(input);
    expect(output).not.toBe(input);
  });

  it('should clone nested arrays recursively', () => {
    const input = [1, [2, 3], [[4]]];
    const output = deepClone(input);
    expect(output).toEqual(input);
    expect(output).not.toBe(input);
    expect(output[1]).not.toBe(input[1]);
  });

  it('should delegate to deepCloneObject for plain objects', () => {
    const input = { a: 1 };
    const output = deepClone(input);
    expect(output).toEqual(input);
    expect(output).not.toBe(input);
  });

  it('should return non-plain objects (like Date, RegExp) as is if not cloned internally', () => {
    const date = new Date();
    const regex = /test/;
    expect(deepClone(date)).toBe(date);
    expect(deepClone(regex)).toBe(regex);
  });

  it('should handle mixed arrays containing objects', () => {
    const input = [1, { x: 1 }];
    const output = deepClone(input);
    expect(output).toEqual([1, { x: 1 }]);
    expect(output).not.toBe(input);
    expect(output[1]).not.toBe(input[1]);
  });
});

