const { normalizeClassOpts } = require('../../../src/options/class');

describe('normalizeClassOpts', () => {
  let ParentError;

  beforeEach(() => {
    ParentError = class extends Error {
      constructor(message) {
        super(message);
        this.name = 'ParentError';
      }
    };
  });

  it('should return the classOpts if it is a plain object', () => {
    const classOpts = { foo: 'bar' };
    const result = normalizeClassOpts(ParentError, classOpts);
    expect(result).toBe(classOpts);
  });

  it('should return an empty object if no classOpts is provided', () => {
    const result = normalizeClassOpts(ParentError);
    expect(result).toEqual({});
  });

  it('should throw a TypeError if classOpts is not a plain object', () => {
    const invalidValues = [
      'string',
      123,
      true,
      [],
      new Date(),
      () => {},
    ];

    invalidValues.forEach((value) => {
      expect(() => normalizeClassOpts(ParentError, value)).toThrow(TypeError);
    });
  });

  it('should throw with the correct error message for non-object input', () => {
    expect(() => normalizeClassOpts(ParentError, 'invalid')).toThrow(
      `The second argument of "${ParentError.name}.subclass()" must be a plain object, not: invalid`
    );
    expect(() => normalizeClassOpts(ParentError, null)).toThrow(
      `The second argument of "${ParentError.name}.subclass()" must be a plain object, not: null`
    );
  });
});

